/* Draws one card per area from window.AREAS (docs/areas.js, generated by
 * scripts/build.rb). Used by the home page and the city pages.
 *   <div class="areas" data-area-cards data-base="../" data-city="seattle"></div>
 * data-base: path from this page to docs/. data-city: only that city's areas.
 * data-show-city: also print the city name on each card. */
"use strict";

(() => {
  const esc = s => String(s ?? "").replace(/[&<>"']/g, ch => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[ch]));
  for (const el of document.querySelectorAll("[data-area-cards]")) {
    const base = el.dataset.base || "";
    const areas = (window.AREAS || []).filter(a => !el.dataset.city || a.city_slug === el.dataset.city);
    el.insertAdjacentHTML("afterbegin", areas.map(a => `
      <a class="area" href="${esc(base + a.path)}">
        <span class="where">${el.dataset.showCity !== undefined ? `${esc(a.city)} · ` : ""}${esc(a.name)}</span>
        <h3>${esc(a.street)}</h3>
        <span class="small">${esc(a.extent)} · ${a.corners} corners at ${a.intersections} intersections</span>
        <span class="counts">
          <span><strong>${a.no_ramp}</strong> no ramp</span>
          <span><strong>${a.one_crossing}</strong> one crossing only</span>
          <span><strong>${a.both_crossings}</strong> fully ramped</span>
          ${a.requests_filed ? `<span><strong>${a.requests_filed}</strong> requests filed</span>` : ""}
        </span>
        <span class="go">See ${esc(a.street)} →</span>
      </a>`).join(""));
  }
})();
